import {permissions,checkPermission} from './visual.mjs';
import {toMarkdown} from './agreement.mjs';
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const labels={allow:'Allowed',ask:'Ask first',never:'Never'};
let token=null,configured=false,message='',file=null,preview=null,pending=null,job=null,result=null,busy=false,epoch=0;
let fields={prompt:'',subject:'',romantic:false,realistic:false,duration:5,resolution:'480',rights:false};
const digest=async input=>[...new Uint8Array(await crypto.subtle.digest('SHA-256',input))].map(x=>x.toString(16).padStart(2,'0')).join('');
async function api(path,body,method='POST',headers={}){
 const response=await fetch('/api/'+path,{method,headers:{...(token?{Authorization:'Bearer '+token}:{}),...(body instanceof ArrayBuffer?{}:{'Content-Type':'application/json'}),...headers},body:body===undefined?undefined:body instanceof ArrayBuffer?body:JSON.stringify(body)});
 const data=await response.json();if(!response.ok)throw new Error(data.error||'The request could not be completed.');return data;
}
export function visualEditor(v){return `<fieldset class="visual-clause"><legend>Visual likeness & generated intimacy</legend><p>Each permission stands on its own. “Ask first” grants no advance permission. The video feature is optional.</p>${permissions.map(([id,label])=>`<label class="permission-row" for="visual-${id}"><span>${esc(label)}</span><select id="visual-${id}" data-visual="${id}">${Object.entries(labels).map(([value,text])=>`<option value="${value}" ${v[id]===value?'selected':''}>${text}</option>`).join('')}</select></label>`).join('')}<p class="field-note">Generating an image does not permit animation. Using a likeness does not permit intimacy. The video feature checks these choices; other platforms still have their own limits.</p></fieldset>`;}
export function visualReview(v){return `<section class="clause"><h3>Visual likeness & generated intimacy</h3><dl class="permission-review">${permissions.map(([id,label])=>`<div><dt>${esc(label)}</dt><dd>${labels[v[id]]}</dd></div>`).join('')}</dl><p>Each permission stands alone. These choices will be checked before the optional YouCam request.</p><button class="text-button" data-edit="3">Edit visual permissions</button></section>`;}
export async function approveVisual(state,markdown){
 const n=++epoch;token=null;pending=null;job=null;result=null;message='Preparing the optional video feature…';
 try{
  const config=await api('config',undefined,'GET');if(n!==epoch)return;configured=config.configured;
  if(!configured){message='Video generation is not connected yet. Add YOUCAM_API_KEY as a secret in the site’s settings. Your agreement is ready to download.';return;}
  const response=await api('agreements',{visual:state.settled.visual,version:state.version,agreementHash:await digest(new TextEncoder().encode(markdown)),reviewed:true});
  if(n!==epoch){await fetch('/api/revoke',{method:'POST',headers:{Authorization:'Bearer '+response.token,'Content-Type':'application/json'},body:'{}'});return;}
  token=response.token;message='Your settled visual terms are ready. Nothing is sent until you review a request.';
 }catch(e){message=e.message;}
}
export function revokeVisual(){
 epoch++;pending=null;job=null;result=null;busy=false;
 if(token){const old=token;token=null;fetch('/api/revoke',{method:'POST',headers:{Authorization:'Bearer '+old,'Content-Type':'application/json'},body:'{}',keepalive:true}).catch(()=>{message='The revocation could not be confirmed. Close this tab; server authorization expires within 24 hours.';});}
}
export function mediaPanel(){
 return `<section class="card media-panel" aria-labelledby="media-title"><div class="card-header"><p class="eyebrow">After the agreement · Optional</p><h2 id="media-title">May I make something for us?</h2><p>A still image, a little movement, and the terms you chose.</p></div><div class="card-body"><p role="status">${esc(message||'Settle your terms to connect the video feature.')}</p>${!token?'<button class="button secondary" id="retry-connection">Check video connection</button>':''}${configured&&token?`<fieldset ${busy||pending?'disabled':''} class="media-fields"><legend class="sr-only">Your video request</legend><label for="source-image">Choose a JPG or PNG</label><input id="source-image" type="file" accept="image/jpeg,image/png"><p class="field-note">Under 10 MB; longest side at most 4096 pixels; aspect ratio from 1:2.5 to 2.5:1.</p>${preview?`<img class="source-preview" src="${esc(preview)}" alt="Your selected source image">`:''}<label for="media-subject">Who is represented?</label><select id="media-subject"><option value="">Choose who appears</option>${[['ai','The AI’s representation'],['me','My likeness'],['us','My likeness and the AI'],['other','A scene or object; no person’s likeness']].map(([v,l])=>`<option value="${v}" ${fields.subject===v?'selected':''}>${l}</option>`).join('')}</select><label for="media-prompt">Describe the motion you want</label><textarea id="media-prompt" maxlength="1500" placeholder="A gentle smile as the camera slowly moves closer…">${esc(fields.prompt)}</textarea><label class="confirmation"><input id="media-romantic" type="checkbox" ${fields.romantic?'checked':''}><span>This includes romance or intimacy.</span></label><label class="confirmation"><input id="media-realistic" type="checkbox" ${fields.realistic?'checked':''}><span>This is or should look photorealistic.</span></label><div class="identities"><label>Length<select id="media-duration"><option value="5" ${fields.duration===5?'selected':''}>5 seconds</option><option value="10" ${fields.duration===10?'selected':''}>10 seconds</option></select></label><label>Resolution<select id="media-resolution">${['480','720','1080'].map(v=>`<option value="${v}" ${fields.resolution===v?'selected':''}>${v}p</option>`).join('')}</select></label></div><label class="confirmation"><input id="media-rights" type="checkbox" ${fields.rights?'checked':''}><span>I may use this image, everyone depicted has agreed to this use, and the categories above accurately describe my request.</span></label><p class="field-note">YouCam receives the image and motion prompt and may expand the prompt using Gemini. Its processing and retention rules apply. This site keeps a permission receipt and request details, not the source image or video. These controls check your declared categories; they do not inspect the image or guarantee the output.</p><p class="field-note">Generation uses the site owner’s YouCam credits. Up to 10 submissions per day across this site. <a href="https://docs.perfectcorp.com/develop/introduction" target="_blank" rel="noreferrer">YouCam documentation and policies</a></p><button class="button" id="prepare-video" ${!file?'disabled':''}>Check my terms</button></fieldset>`:''}${pending?`<div class="request-review"><h3>Review this exact request</h3><p>${esc(pending.descriptor.prompt)}</p><p>${pending.descriptor.duration} seconds · ${pending.descriptor.resolution}p · ${esc(fields.subject)}</p>${pending.ask.length?`<p>Your agreement requires separate permission for:</p>${pending.ask.map(id=>`<label class="confirmation"><input type="checkbox" data-once="${id}"><span>${esc(permissions.find(([key])=>key===id)[1])} — allow for this request only</span></label>`).join('')}`:'<p>Your agreement allows each required category.</p>'}<label class="confirmation"><input id="processing-confirm" type="checkbox"><span>Send this image and motion prompt to YouCam and use credits for this one video.</span></label><button class="button" id="submit-video" ${busy?'disabled':''}>Create this video</button> <button class="button secondary" id="cancel-video" ${busy?'disabled':''}>Cancel</button></div>`:''}${job&&!result?.url?`<button class="button secondary" id="check-video" ${busy?'disabled':''}>Check video status</button>`:''}${result?.url?`<div class="video-result"><p class="eyebrow">Generated media · YouCam</p><video controls playsinline controlslist="nodownload" preload="metadata" src="${esc(result.url)}"></video><p class="field-note">Temporary provider link. Viewing a video makes it accessible to your browser; these controls cannot prevent screenshots or copying.</p><div class="button-group"><button class="button secondary" data-media-action="save">Save video</button><button class="button secondary" data-media-action="share">Copy video link</button></div><div id="media-action-confirm"></div></div>`:''}${result?.receipt?`<details class="receipt"><summary>Why was this allowed?</summary><p>Agreement version ${result.receipt.agreementVersion} · ${esc(result.receipt.transformation)}</p><ul>${result.receipt.permissions.map(p=>`<li>${esc(permissions.find(([id])=>id===p.key)?.[1]||p.key)}: ${labels[p.setting]}${p.setting==='ask'?' · approved for this request':''}</li>`).join('')}</ul><button class="text-button" id="download-receipt">Download consent receipt</button></details>`:''}</div></section>`;
}
export function bindMedia(getState,render){
 const on=(id,event,fn)=>document.getElementById(id)?.addEventListener(event,fn);
 on('retry-connection','click',async()=>{if(busy)return;busy=true;await approveVisual(getState(),toMarkdown(getState()));busy=false;render();});
 on('source-image','change',async e=>{try{const candidate=e.target.files[0];if(!candidate)return;if(candidate.size>=10000000||!['image/jpeg','image/png'].includes(candidate.type))throw new Error('Choose a JPG or PNG smaller than 10 MB.');const bitmap=await createImageBitmap(candidate);const {width,height}=bitmap;bitmap.close();if(Math.max(width,height)>4096||width/height<0.4||width/height>2.5)throw new Error('Use an image within the displayed dimension limits.');if(preview)URL.revokeObjectURL(preview);file=candidate;preview=URL.createObjectURL(file);pending=null;message='Image selected. It has not been uploaded.';}catch(e){file=null;message=e.message;}render();});
 for(const [id,key,event] of [['media-prompt','prompt','input'],['media-subject','subject','change'],['media-romantic','romantic','change'],['media-realistic','realistic','change'],['media-rights','rights','change'],['media-duration','duration','change'],['media-resolution','resolution','change']])on(id,event,e=>{fields[key]=e.target.type==='checkbox'?e.target.checked:key==='duration'?Number(e.target.value):e.target.value;pending=null;});
 on('prepare-video','click',async()=>{if(busy)return;epoch++;job=null;result=null;busy=true;render();try{if(!getState().settled||!file)throw new Error('Settle the agreement and choose an image first.');const descriptor={...fields,sha256:await digest(await file.arrayBuffer()),type:file.type,size:file.size};const check=checkPermission(getState().settled.visual,descriptor);if(check.denied.length)throw new Error('Your agreement says Never for: '+check.denied.map(id=>permissions.find(([k])=>k===id)[1]).join(', ')+'. No image was sent.');const response=await api('prepare',{descriptor});pending={...response,descriptor};message='Review the permissions below. The image is still in this tab.';}catch(e){message=e.message;}busy=false;render();});
 on('cancel-video','click',()=>{pending=null;message='Cancelled. No image was sent.';render();});
 const check=async()=>{if(!job||busy)return;busy=true;const n=epoch;try{const response=await api('jobs/'+job,undefined,'GET');if(n!==epoch)return;result=response;message=response.status==='success'?'Your generated video is ready.':response.status==='error'?(response.message||'Generation failed.'):'YouCam is still processing. You can check again.';if(response.status==='running')setTimeout(()=>{if(n===epoch)check();},10000);}catch(e){message=e.message+' Use Check video status to retry the status check.';}finally{busy=false;if(n===epoch)render();}};
 on('check-video','click',check);
 on('submit-video','click',async()=>{if(busy||!pending)return;const approved=[...document.querySelectorAll('[data-once]:checked')].map(x=>x.dataset.once);if(pending.ask.some(id=>!approved.includes(id))||!document.querySelector('#processing-confirm').checked){message='Approve each requested permission and confirm processing, or cancel.';render();return;}const id=pending.id,n=epoch;job=id;busy=true;message='Sending your approved request to YouCam…';render();try{const response=await api('jobs/'+id+'/submit',await file.arrayBuffer(),'POST',{'Content-Type':file.type,'X-Visual-Approval':JSON.stringify(approved),'X-Confirm-Processing':'yes'});if(n!==epoch)return;job=id;result=response;pending=null;message='YouCam is creating your video. Checking every 10 seconds.';setTimeout(()=>{if(n===epoch)check();},10000);}catch(e){pending=null;message=e.message;}finally{busy=false;if(n===epoch)render();}});
 document.querySelectorAll('[data-media-action]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.mediaAction,setting=getState().settled.visual[action];if(setting==='never'){message='Your agreement does not permit '+(action==='save'?'saving this video.':'sharing or exporting this video.');render();return;}const container=document.querySelector('#media-action-confirm');container.replaceChildren();const p=document.createElement('p');p.textContent=setting==='ask'?'Your agreement requires permission. Allow this '+action+' once?':'Your agreement permits this '+action+'. Continue?';const yes=document.createElement('button');yes.className='button';yes.textContent=action==='save'?'Allow and open video':'Allow and get link';yes.onclick=async()=>{yes.disabled=true;try{const data=await api('jobs/'+job+'/export',{action,confirmed:true});result={...result,receipt:data.receipt};if(action==='share'){await navigator.clipboard.writeText(data.url);message='Video link copied. It expires at YouCam.';}else{const a=document.createElement('a');a.href=data.url;a.target='_blank';a.rel='noreferrer';a.textContent='Open video to save';container.replaceChildren(a);message='Use the video’s browser controls to save it.';return;}render();}catch(e){message=e.message;render();}};container.append(p,yes);}));
 on('download-receipt','click',()=>{const url=URL.createObjectURL(new Blob([JSON.stringify(result.receipt,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='on-our-terms-consent-receipt.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
}

window.addEventListener('pagehide',revokeVisual);

